namespace MyApp.Evals.Tests;

internal static class RepoRoot
{
    public static string Find()
    {
        var dir = AppContext.BaseDirectory;
        while (dir is not null)
        {
            if (File.Exists(Path.Combine(dir, "MyApp.slnx")) ||
                File.Exists(Path.Combine(dir, "MyApp.sln")))
                return dir;
            dir = Directory.GetParent(dir)?.FullName;
        }

        // Fallback: walk up from the test assembly location
        return Path.GetFullPath(Path.Combine(AppContext.BaseDirectory, "..", "..", "..", ".."));
    }
}

namespace MyApp.Evals.Tests;

/// <summary>
/// Resolves the same IChatClient the app uses, by building a minimal
/// host that mirrors the app's DI registration.
/// Detected: AddAzureOpenAIChatClient at AppHost.cs:2
/// Deployment alias: "chat" → gpt-4o-mini
/// </summary>
internal static class AgentChatClientFactory
{
    public static IChatClient Create()
    {
        var builder = Host.CreateApplicationBuilder();

        // In test hosts (dotnet test), the entry assembly is testhost.exe so
        // user-secrets are NOT auto-loaded by CreateApplicationBuilder.
        // Add them explicitly from THIS assembly's UserSecretsId.
        builder.Configuration.AddUserSecrets(typeof(AgentChatClientFactory).Assembly, optional: true);

        // Mirror the app's registration:
        // builder.AddAzureOpenAIChatClient("chat", "gpt-4o-mini");
        builder.AddAzureOpenAIChatClient("chat", "gpt-4o-mini");

        var host = builder.Build();
        try
        {
            return host.Services.GetRequiredService<IChatClient>();
        }
        catch (InvalidOperationException ex)
        {
            throw new InvalidOperationException(
                "EVAL_USE_REAL_AGENT=1 but IChatClient could not be resolved. " +
                "The detected registration (AddAzureOpenAIChatClient) reads connection " +
                "string \"chat\" from configuration. Aspire's AppHost populates this at " +
                "runtime, but `dotnet test` runs standalone. Wire one of:\n" +
                "  # Key-based auth:\n" +
                "  dotnet user-secrets set \"ConnectionStrings:chat\" " +
                "\"Endpoint=https://<host>.services.ai.azure.com/models;Key=<key>;DeploymentId=chat\" " +
                "--project MyApp.Evals.Tests\n" +
                "  # Entra-ID auth (DefaultAzureCredential):\n" +
                "  dotnet user-secrets set \"ConnectionStrings:chat\" " +
                "\"Endpoint=https://<host>.services.ai.azure.com/models;DeploymentId=chat\" " +
                "--project MyApp.Evals.Tests\n" +
                "Note: the hostname strips dashes from the resource name " +
                "(resource `foundry-abc` -> host `foundryabc.services.ai.azure.com`).",
                ex);
        }
    }
}

namespace MyApp.Evals.Tests;

/// <summary>
/// Stub IChatClient used when EVAL_USE_REAL_AGENT is unset.
/// Returns a canned response so NLP evaluators produce meaningful metrics
/// without requiring any credentials.
/// </summary>
internal sealed class StubChatClient : IChatClient
{
    public Task<ChatResponse> GetResponseAsync(
        IEnumerable<ChatMessage> messages,
        ChatOptions? options = null,
        CancellationToken cancellationToken = default)
    {
        var response = new ChatResponse(new ChatMessage(ChatRole.Assistant,
            "This is a stub response for evaluation purposes. " +
            "Set EVAL_USE_REAL_AGENT=1 with valid credentials to test against the real model."));
        return Task.FromResult(response);
    }

    public IAsyncEnumerable<ChatResponseUpdate> GetStreamingResponseAsync(
        IEnumerable<ChatMessage> messages,
        ChatOptions? options = null,
        CancellationToken cancellationToken = default) =>
        throw new NotSupportedException("Streaming not supported in stub mode.");

    public object? GetService(Type serviceType, object? serviceKey = null) => null;

    public void Dispose() { }
}

namespace MyApp.Evals.Tests;

internal static class Wire
{
    public static IChatClient ResolveAgentClient() =>
        EvalEnv.UseRealAgent ? AgentChatClientFactory.Create() : new StubChatClient();

    public static IChatClient ResolveJudgeClient(IChatClient agentClient)
    {
        var judgeOverride = Environment.GetEnvironmentVariable("EVAL_JUDGE_DEPLOYMENT_NAME");
        if (string.IsNullOrEmpty(judgeOverride))
            return agentClient;

        // Build a separate client for the judge model
        var builder = Host.CreateApplicationBuilder();
        builder.Configuration.AddUserSecrets(typeof(AgentChatClientFactory).Assembly, optional: true);
        builder.AddAzureOpenAIChatClient("chat", judgeOverride);
        var host = builder.Build();
        return host.Services.GetRequiredService<IChatClient>();
    }
}

